{
 "rules": [
  {
   "id": "r1",
   "text": "If the chart's y-axis is read as temperature in °C and the printed point labels are taken as the yearly values, then the 2005-to-2015 change is the difference between the first and last printed labels; a large absolute difference across the review period is the visible basis for a 'substantial' trend.",
   "component": "encoding/task relation",
   "conditions": "Assumes the printed labels are the intended data values and that 'substantial' is judged by magnitude of change across the period, as stated in the routing criterion."
  },
  {
   "id": "r2",
   "text": "If the routing workflow requires a defined threshold to distinguish 'substantial' from 'routine' change, and no such threshold is printed on the chart or in the public task fields, then the chart alone cannot determine which route is correct; the magnitude can be computed but its classification remains open.",
   "component": "task-to-action relation",
   "conditions": "Applies when no policy table or numeric cutoff is supplied; the absence of a threshold is a support gap, not a reason to pick a route."
  },
  {
   "id": "r3",
   "text": "If the printed labels are treated as literal inscriptions rather than validated data, the visible fact is only that a descending sequence of labels is printed from 2005 to 2015; whether this constitutes a 'decline' in the measured quantity depends on the axis-to-quantity mapping, which is not independently verified by the image.",
   "component": "series/axis/entity binding",
   "conditions": "Scope: raw visual marks and literal text only; no decoded metric trend is asserted as fact."
  }
 ],
 "chains": [
  {
   "chain_id": "base_c1",
   "rule_id": "r1",
   "observations": [
    {
     "ref": "chart_1",
     "location": "top-left data point, 2005",
     "content": "A black dot is printed at the 2005 x-position with the literal inscription '$24.0°C' above it."
    },
    {
     "ref": "chart_1",
     "location": "bottom-right data point, 2015",
     "content": "A black dot is printed at the 2015 x-position with the literal inscription '$10.0°C' above it."
    },
    {
     "ref": "chart_1",
     "location": "y-axis label",
     "content": "The vertical axis is labeled 'Temperature (°C)' with printed ticks at 0, 5, 10, 15, 20."
    }
   ],
   "task_evidence": [
    {
     "ref": "public_task",
     "path": "/companion_fields/3/value",
     "content": "Magnitude of change across the review period"
    },
    {
     "ref": "public_task",
     "path": "/option_labels/0",
     "content": "Escalate the 2005-2015 temperature decline for follow-up"
    }
   ],
   "claim_kind": "supports_action",
   "option_label": "Escalate the 2005-2015 temperature decline for follow-up",
   "claim": "Under the assumption that the printed labels are the data values, the visible change from $24.0°C to $10.0°C is a 14.0°C drop, which is a large magnitude across the review period and motivates the escalate route."
  },
  {
   "chain_id": "base_c2",
   "rule_id": "r2",
   "observations": [
    {
     "ref": "chart_1",
     "location": "entire chart area",
     "content": "No threshold line, annotation, or legend entry indicating a 'substantial' cutoff is visible on the chart."
    }
   ],
   "task_evidence": [
    {
     "ref": "public_task",
     "path": "/companion_fields/2/value",
     "content": "Substantial trend follow-up"
    },
    {
     "ref": "public_task",
     "path": "/policy_tables",
     "content": null
    }
   ],
   "claim_kind": "underdetermined",
   "option_label": null,
   "claim": "The public task names a 'substantial trend workflow' and a routing criterion of magnitude, but supplies no numeric threshold or policy table; therefore the chart's 14.0°C change cannot be definitively classified as substantial versus routine from the visible evidence alone."
  },
  {
   "chain_id": "base_c3",
   "rule_id": "r3",
   "observations": [
    {
     "ref": "chart_1",
     "location": "data point labels, 2005 through 2015",
     "content": "A sequence of literal inscriptions is printed above each dot: $24.0°C, $22.8°C, $21.9°C, $20.3°C, $19.1°C, $16.3°C, $15.4°C, $13.9°C, $12.2°C, $10.0°C, in descending order left to right."
    },
    {
     "ref": "chart_1",
     "location": "line connecting dots",
     "content": "A blue line connects the dots in a generally downward slope from the 2005 dot to the 2015 dot."
    }
   ],
   "task_evidence": [
    {
     "ref": "public_task",
     "path": "/chart_reference",
     "content": "Use the charted yearly temperature readings as the basis for this routing decision."
    }
   ],
   "claim_kind": "challenges_support",
   "option_label": null,
   "claim": "The visible marks show a descending sequence of printed labels and a downward line, but the labels are literal inscriptions, not validated measurements; the 'decline' interpretation depends on accepting the axis-to-quantity mapping, which the image does not independently confirm."
  }
 ]
}
